#include <iostream>
#include <vector>
#include <functional>
using namespace std;

using Handler = function<bool(string)>;

struct Middleware {
    string name;
    Handler handle;
};

class Pipeline {
    vector<Middleware> middlewares;
public:
    void use(const string& name, Handler handler) {
        middlewares.push_back({name, handler});
    }
    bool execute(const string& request) {
        bool result = true;
        for (auto& mw : middlewares) {
            cout << "[" << mw.name << "] ";
            result = mw.handle(request);
            if (!result) break;
        }
        return result;
    }
};

int main() {
    Pipeline p;
    p.use("Logger", [](string req) { cout << "Request: " << req << endl; return true; });
    p.use("Auth", [](string req) {
        if (req.find("token") == string::npos) { cout << "DENIED" << endl; return false; }
        cout << "OK" << endl; return true;
    });
    p.use("Handler", [](string req) { cout << "Processed: " << req << endl; return true; });
    p.execute("GET /data token=abc");
    return 0;
}
